<template>
  <div class="management-page">
    <section class="management-stats">
      <article v-for="stat in stats" :key="stat.label" class="surface management-stat"><span class="metric-icon" :class="stat.tone"><component :is="stat.icon" :size="18" /></span><div :data-note="stat.note"><small>{{ stat.label }}</small><strong>{{ stat.value }} <em>项</em></strong></div></article>
    </section>
    <section class="surface management-list">
      <div class="card-heading check-heading"><div><span class="section-kicker">01 / AI 核查</span><h2>核查任务</h2></div><span class="history-count">共 {{ filtered.length }} 个项目</span></div>
      <div class="management-toolbar"><div class="management-tools"><div class="check-tabs"><button v-for="type in ['室内', '现场']" :key="type" class="button" :class="type === activeType ? 'button-primary' : 'button-secondary'" @click="activeType = type">{{ type }}检测</button></div><label class="search-box"><Search :size="16" /><input v-model="keyword" type="search" placeholder="搜索项目、机构或报告编号" /></label></div><div class="management-list-actions"><label class="check-all"><input v-model="selectAll" type="checkbox" @change="toggleAll" /> 全选待核查</label><button class="button button-primary" @click="batchCheck"><Play :size="15" /> 批量核查</button></div></div>
      <div class="management-table-wrap"><table class="management-table check-table"><thead><tr><th>选择</th><th>项目 / 报告</th><th>检测机构</th><th>核查状态</th><th>问题数</th><th>操作</th></tr></thead><tbody><tr v-for="project in filtered" :key="project.id"><td><input v-model="selected" type="checkbox" :value="project.id" :disabled="project.st !== '未核查'" /></td><td><div class="management-name"><span class="table-file-icon"><FileText :size="17" /></span><strong>{{ project.name }}<small>{{ project.id }} · {{ project.rno }}</small></strong></div></td><td class="truncate-cell" :title="project.org">{{ project.org }}</td><td><span class="table-status" :class="{ inactive: project.st !== '已核查' }"><span></span>{{ project.st }}</span></td><td><span class="count-dot"></span>{{ totalProblems(project) }}</td><td><div class="row-actions"><button @click="detailProject = project">查看详情</button><button :disabled="project.st !== '未核查'" @click="runSingle(project)">核查</button><button @click="openResult(project)">核查结果</button></div></td></tr></tbody></table><div v-if="!filtered.length" class="empty-state"><ClipboardCheck :size="26" /><strong>暂无项目</strong></div></div>
    </section>
    <div v-if="detailProject" class="modal-backdrop" @click.self="detailProject = null"><section class="management-modal" role="dialog" aria-modal="true" aria-label="核查项目详情"><div class="management-modal-head"><div><span class="section-kicker">{{ detailProject.id }} · {{ detailProject.rno }}</span><h2>核查项目详情</h2></div><button class="icon-button" aria-label="关闭" @click="detailProject = null"><X :size="18" /></button></div><div class="management-detail"><dl><div><dt>工程项目</dt><dd>{{ detailProject.name }}</dd></div><div><dt>检测机构</dt><dd>{{ detailProject.org }}</dd></div><div><dt>检测类型</dt><dd>{{ detailProject.type }}</dd></div><div><dt>检测参数</dt><dd>{{ detailProject.param }}</dd></div><div><dt>核查状态</dt><dd>{{ detailProject.st }}</dd></div><div><dt>启用规则</dt><dd>{{ ruleFor(detailProject.type, detailProject.param)?.items.filter(item => item.on).length || 0 }} 项</dd></div><div><dt>问题数量</dt><dd>{{ totalProblems(detailProject) }} 项</dd></div><div><dt>问题单</dt><dd>{{ provincialState.submits[detailProject.rno] ? `已于 ${provincialState.submits[detailProject.rno]} 提交` : '未提交' }}</dd></div></dl><div class="management-modal-foot"><button class="button button-secondary" @click="detailProject = null">关闭</button><button class="button button-primary" @click="openResult(detailProject); detailProject = null">查看核查结果</button></div></div></section></div>
    <div v-if="activeProject" class="modal-backdrop" @click.self="activeProject = null"><section class="management-modal result-modal" role="dialog" aria-modal="true" aria-label="AI 核查结果"><div class="management-modal-head"><div><span class="section-kicker">{{ activeProject.id }} · {{ activeProject.rno }}</span><h2>{{ activeProject.name }}</h2></div><button class="icon-button" aria-label="关闭" @click="activeProject = null"><X :size="18" /></button></div><div class="management-detail"><div class="result-meta"><span class="table-status"><span></span>{{ activeProject.st }}</span><span>{{ activeProject.org }}</span><span>{{ activeProject.type }} · {{ activeProject.param }}</span></div><div v-if="result.rule" class="result-basis">核查依据：知识库及规则配置 · {{ result.rule.param }} · {{ result.rule.std }} · {{ result.rule.items.filter(item => item.on).length }} 项启用规则</div><p v-else class="form-error">该检测参数尚未配置核查规则，无法生成核查结论。</p><div class="result-columns"><section><h3>基础核查</h3><div v-for="item in result.base" :key="item.text" class="result-item"><span :class="item.status">{{ item.status === 'pass' ? '✓' : '!' }}</span><div><strong>{{ item.text }}</strong><small>{{ item.detail }}</small></div></div><p v-if="!result.base.length" class="helper">暂无核查项</p></section><section><h3>影像核查</h3><div v-for="item in result.image" :key="item.text" class="result-item"><span :class="item.status">{{ item.status === 'pass' ? '✓' : '!' }}</span><div><strong>{{ item.text }}</strong><small>{{ item.detail }}</small></div></div><p v-if="!result.image.length" class="helper">暂无影像核查项</p></section></div><h3 class="problem-heading">问题清单 · {{ result.problems.length + preAnomalies.length }} 项</h3><div v-for="problem in result.problems" :key="problem.id" class="problem-item"><strong>[{{ problem.level }}] {{ problem.text }}</strong><small>{{ problem.id }} · 对应核查项：{{ problem.rule }}</small></div><div v-for="problem in preAnomalies" :key="problem[6]" class="problem-item"><strong>[{{ problem[5] }}] {{ problem[7] }}</strong><small>{{ problem[6] }} · 采集端初筛异常</small></div><p v-if="!result.problems.length && !preAnomalies.length" class="helper">本次核查未发现问题</p><div class="management-modal-foot"><span v-if="provincialState.submits[activeProject.rno]" class="helper">已于 {{ provincialState.submits[activeProject.rno] }} 提交并推送至 {{ activeProject.org }}</span><button class="button button-secondary" @click="activeProject = null">关闭</button><button v-if="activeProject.st === '已核查' && totalProblems(activeProject) && !provincialState.submits[activeProject.rno] && result.rule" class="button button-primary" @click="submitActive">提交问题清单</button></div></div></section></div>
    <div v-if="notice" class="toast" role="status">{{ notice }}</div>
  </div>
</template>

<script setup>
import { computed, ref } from 'vue'
import { ClipboardCheck, FileText, ListChecks, Play, Search, TriangleAlert, X } from 'lucide-vue-next'
import { checkRows, provincialState, ruleFor, runChecks, scopedProjects, submitProblems } from '../state/provincialState'

const activeType = ref('室内'), keyword = ref(''), selected = ref([]), selectAll = ref(false), activeProject = ref(null), detailProject = ref(null), notice = ref('')
const filtered = computed(() => scopedProjects().filter(item => item.type === activeType.value && (!keyword.value || [item.name, item.org, item.rno, item.param].join(' ').toLowerCase().includes(keyword.value.toLowerCase()))))
const result = computed(() => activeProject.value ? checkRows(activeProject.value) : { rule: null, base: [], image: [], problems: [] })
const preAnomalies = computed(() => activeProject.value ? provincialState.issues.filter(item => item[0] === activeProject.value.rno && item[3] === 'pre') : [])
const stats = computed(() => [
  { label: '核查项目', value: scopedProjects().length, note: '当前类型的核查任务', tone: 'indigo', icon: ClipboardCheck },
  { label: '已完成核查', value: scopedProjects().filter(item => item.st === '已核查').length, note: '已生成核查结果的项目', tone: 'teal', icon: ListChecks },
  { label: '发现问题', value: scopedProjects().reduce((total, item) => total + totalProblems(item), 0), note: '当前类型累计问题数', tone: 'amber', icon: TriangleAlert }
])
function totalProblems(project) { return checkRows(project).problems.length + provincialState.issues.filter(item => item[0] === project.rno && item[3] === 'pre').length }
function toggleAll() { selected.value = selectAll.value ? filtered.value.filter(item => item.st === '未核查').map(item => item.id) : [] }
function announce(text) { notice.value = text; setTimeout(() => { notice.value = '' }, 2500) }
function batchCheck() { const count = runChecks(selected.value); selected.value = []; selectAll.value = false; announce(count ? `正在核查 ${count} 个项目` : '请先勾选待核查项目') }
function runSingle(project) { if (runChecks([project.id])) announce(`正在核查「${project.name}」`) }
function openResult(project) { activeProject.value = project }
function submitActive() { if (submitProblems(activeProject.value)) announce('问题清单已提交并推送至检测机构') }
</script>

<style scoped>
.check-heading{margin-bottom:20px}.check-tabs{display:flex;gap:8px}.check-all{display:flex;align-items:center;gap:6px;color:#68788f;font-size:11px;white-space:nowrap}.check-table{min-width:0}.check-table th:first-child{width:8%}.check-table th:nth-child(2){width:47%}.check-table th:nth-child(3){width:16%}.check-table th:last-child{width:29%}.check-table td{height:80px}.check-table .row-actions{flex-wrap:wrap}.management-name{width:min(100%,250px)}.management-name strong{display:flex;flex-direction:column;gap:5px}.management-name small{font-size:9px;color:#8b98aa;font-weight:500}.edition-line{display:block;margin-top:5px;color:#8b98aa;font-size:9px}.result-modal{width:min(900px,100%)}.result-meta{display:flex;align-items:center;gap:14px;color:#68788f;font-size:11px;flex-wrap:wrap}.result-basis{margin:17px 0;padding:12px;background:#f7f9fd;border-left:3px solid #235fd6;border-radius:8px;font-size:11px;color:#40516b}.result-columns{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:20px}.result-columns section{min-width:0}.result-columns h3,.problem-heading{font-size:13px;color:#243248;margin:0 0 12px}.result-item{display:flex;align-items:flex-start;gap:10px;padding:10px 0;border-bottom:1px solid #eaf0ff}.result-item>span{width:24px;height:24px;border-radius:8px;display:grid;place-items:center;flex:none;font-size:12px;font-weight:700}.result-item>span.pass{background:#e9f8f2;color:#248b72}.result-item>span.warn,.result-item>span.pending{background:#fceff2;color:#b84462}.result-item strong,.problem-item strong{display:block;font-size:11px;color:#40516b;line-height:1.5}.result-item small,.problem-item small{display:block;color:#8b98aa;font-size:10px;line-height:1.6;margin-top:4px}.problem-heading{margin-top:23px}.problem-item{padding:12px 14px;margin:8px 0;border:1px solid #e4e9f0;border-radius:11px;background:#fafbfd}.helper{color:#8b98aa;font-size:10px}@media(max-width:670px){.result-columns{grid-template-columns:1fr}}
.check-table th:first-child{width:6%}.check-table th:nth-child(2){width:30%}.check-table th:nth-child(3){width:21%}.check-table th:nth-child(4){width:15%}.check-table th:nth-child(5){width:9%}.check-table th:last-child{width:19%}.check-table .truncate-cell{overflow:hidden;text-overflow:ellipsis}
</style>
